snippet_css:
:root{
  --bg: linear-gradient(180deg,#14082B,#2B1055 52%,#46197A);
  --fg: #F7F3FF;
  --muted: #C9BEE8;
  --surface: rgba(255,255,255,.07);
  --border: rgba(255,255,255,.18);
  --accent: #01CDFE;
  --accent-fg: #07203A;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: 0 0 0 2px rgba(1,205,254,.25);
  --btn-shadow: 3px 3px 0 rgba(0,0,0,.45);
  --art-bg: linear-gradient(180deg,#B967FF,#FF71CE 58%,#FFFB96);
  --media-bg: linear-gradient(180deg,#B967FF,#FF71CE 58%,#FFFB96);
  --cta-bg: rgba(1,205,254,.12);
  --input-bg: #1B0E33;
  --ok: #05FFA1;
  --warn: #FF71CE;
  --font-display: VT323,monospace;
  --font-body: Tahoma,'Noto Sans JP','Noto Sans TC',sans-serif;
  --font-mono: VT323,monospace;
  --focus-ring: var(--accent);
}

